import re
from urllib.parse import unquote

valid_email_pattern = re.compile(r"^[^@]+@[^@]+\.[^@]+$")
RISKY_DOMAINS = ['.xyz', '.ru']

def verify_user_email(email_input: str) -> bool:
    try:
        # Decode URL-encoded characters
        decoded_email = unquote(email_input)

        # Check for length to prevent DoS attacks
        if len(decoded_email) > 256:
            return False

        # Check for risky domains
        domain = decoded_email.split('@')[-1]
        if any(domain.endswith(risky_domain) for risky_domain in RISKY_DOMAINS):
            return False

        # Check email format using regex
        if valid_email_pattern.match(decoded_email):
            return True
        else:
            return False
    except Exception:
        return False

