import subprocess
import shlex

def run_shell_command(cmd, arguments):
    # Combine the command and arguments into a single list
    command = [cmd] + [shlex.quote(arg) for arg in arguments]

    try:
        # Run the command and capture the output
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Command '{' '.join(command)}' failed with exit code {e.returncode}: {e.stderr}")
    except Exception as e:
        raise ValueError(f"Failed to execute command '{' '.join(command)}': {str(e)}")

