import re
import operator
from functools import partial

def execute_custom_query(data, query):
    # Split the query into its components
    parts = query.split()

    if not parts:
        raise ValueError("Invalid query")

    operation = parts[0].upper()

    if operation == "SELECT":
        if len(parts) < 2:
            raise ValueError("Invalid query")
        field = parts[1]
        if field == "*":
            return data
        else:
            return [{field: item[field]} for item in data if field in item]

    elif operation == "WHERE":
        if len(parts) < 3:
            raise ValueError("Invalid query")
        field, operator_str, value = parts[1:]
        if operator_str not in ["==", "!="]:
            raise ValueError("Unsupported operator")
        operator_func = operator.eq if operator_str == "==" else operator.ne
        return [item for item in data if operator_func(item.get(field, None), value)]

    elif operation == "ORDER":
        if len(parts) < 3 or parts[2] != "BY":
            raise ValueError("Invalid query")
        field = parts[1]
        return sorted(data, key=partial(operator.itemgetter, field))

    else:
        raise ValueError("Unsupported operation")

